use crate::{AgentStatus,AiroRequest,BuilderCommand};
#[derive(Debug,Clone,PartialEq,Eq)] pub struct AgentPlan{pub agent:String,pub status:AgentStatus,pub reason:String}
#[derive(Debug,Clone,PartialEq,Eq)] pub struct Route{pub command:BuilderCommand,pub agents:Vec<AgentPlan>}
pub fn route(r:&AiroRequest)->Route{let command=crate::classify_command(r);let agents=match &command{BuilderCommand::Plan(_)=>vec![p("orchestrator","build the living plan"),p("gameplay","identify gameplay systems"),p("world","identify world work"),p("testing","define acceptance tests")],BuilderCommand::Test=>vec![p("testing","run validation")],BuilderCommand::Fix=>vec![p("repair","diagnose failure"),p("testing","verify repair")],BuilderCommand::Tasks=>vec![p("orchestrator","summarize tasks")],BuilderCommand::Message(_)=>vec![p("orchestrator","interpret and route")]};Route{command,agents}}
fn p(a:&str,r:&str)->AgentPlan{AgentPlan{agent:a.into(),status:AgentStatus::Idle,reason:r.into()}}
#[cfg(test)]mod tests{use super::*;#[test]fn plan_routes(){let r=route(&AiroRequest::new("/plan multiplayer"));assert!(r.agents.iter().any(|a|a.agent=="world"));}}